/**
 * Orders Service
 *
 * Handles order creation, status transitions, and queries.
 * Order numbers are generated by the database (A2K-YYYY-NNNNNN).
 * All critical data is frozen as snapshots at creation time.
 */

import { supabase } from '@/lib/supabase'
import type { Order, OrderItem, OrderStatusHistory, OrderStatus } from '@/lib/supabase/types'

// ============================================================
// Order queries
// ============================================================

export async function getOrderById(
  orderId: string,
): Promise<{ data: Order | null; error: string | null }> {
  const client = supabase()
  if (!client) return { data: null, error: 'Supabase not configured' }

  const { data, error } = await client
    .from('orders')
    .select('*')
    .eq('id', orderId)
    .single()

  return { data, error: error?.message ?? null }
}

export async function getOrderByNumber(
  orderNumber: string,
): Promise<{ data: Order | null; error: string | null }> {
  const client = supabase()
  if (!client) return { data: null, error: 'Supabase not configured' }

  const { data, error } = await client
    .from('orders')
    .select('*')
    .eq('order_number', orderNumber)
    .single()

  return { data, error: error?.message ?? null }
}

export async function getCustomerOrders(
  customerId: string,
  options?: { limit?: number; offset?: number },
): Promise<{ data: Order[] | null; error: string | null }> {
  const client = supabase()
  if (!client) return { data: null, error: 'Supabase not configured' }

  let query = client
    .from('orders')
    .select('*')
    .eq('customer_id', customerId)
    .order('created_at', { ascending: false })

  if (options?.limit) {
    query = query.limit(options.limit)
  }
  if (options?.offset) {
    query = query.range(options.offset, options.offset + (options.limit ?? 20) - 1)
  }

  const { data, error } = await query
  return { data, error: error?.message ?? null }
}

