// ============================================================
// Order creation
// ============================================================

export interface CreateOrderParams {
  customerId: string
  addressId?: string
  deliveryMethod: 'shipping' | 'pickup'
  items: Array<{
    productId: string
    variantId?: string
    productName: string
    productSku: string
    variantName?: string
    price: number
    quantity: number
    subtotal: number
    discount?: number
  }>
  subtotal: number
  discountTotal?: number
  shippingCost?: number
  total: number
  currency?: string
  exchangeRate?: number
  totalLocal?: number
  paymentMethodId?: string
  couponId?: string
  promotionId?: string
  customerNotes?: string
  reservationExpiresAt?: string
}

/**
 * Create a new order with items.
 * Order number is auto-generated by the database.
 * All financial values are frozen at creation time.
 */
export async function createOrder(
  params: CreateOrderParams,
): Promise<{ data: Order | null; error: string | null }> {
  const client = supabase()
  if (!client) return { data: null, error: 'Supabase not configured' }

  // Create the order
  const { data: order, error: orderError } = await client
    .from('orders')
    .insert({
      customer_id: params.customerId,
      address_id: params.addressId ?? null,
      delivery_method: params.deliveryMethod,
      status: 'pending_payment',
      subtotal: params.subtotal,
      discount_total: params.discountTotal ?? 0,
      shipping_cost: params.shippingCost ?? 0,
      total: params.total,
      currency: params.currency ?? 'USD',
      exchange_rate: params.exchangeRate ?? null,
      total_local: params.totalLocal ?? null,
      payment_method_id: params.paymentMethodId ?? null,
      coupon_id: params.couponId ?? null,
      promotion_id: params.promotionId ?? null,
      customer_notes: params.customerNotes ?? null,
      reservation_expires_at: params.reservationExpiresAt ?? null,
    })
    .select()
    .single()

  if (orderError) return { data: null, error: orderError.message }

  // Create order items (snapshots)
  const itemsToInsert = params.items.map((item) => ({
    order_id: order.id,
    product_id: item.productId,
    variant_id: item.variantId ?? null,
    product_name: item.productName,
    product_sku: item.productSku,
    variant_name: item.variantName ?? null,
    price: item.price,
    quantity: item.quantity,
    subtotal: item.subtotal,
    discount: item.discount ?? 0,
  }))

  const { error: itemsError } = await client
    .from('order_items')
    .insert(itemsToInsert)

  if (itemsError) return { data: null, error: itemsError.message }

  return { data: order, error: null }
}

// ============================================================
// Status transitions
// ============================================================

/**
 * Valid status transitions.
 * Any transition not listed here is invalid.
 */
const VALID_TRANSITIONS: Record<OrderStatus, OrderStatus[]> = {
  pending_payment: ['payment_verification', 'payment_approved', 'cancelled', 'cancelled_expired'],
  payment_verification: ['payment_approved', 'payment_rejected'],
  payment_approved: ['preparing', 'cancelled'],
  preparing: ['shipped', 'cancelled'],
  shipped: ['delivered', 'returned'],
  delivered: ['returned'],
  cancelled: [],
  cancelled_expired: [],
  payment_rejected: [],
  returned: [],
}

export function isValidTransition(
  currentStatus: OrderStatus,
  newStatus: OrderStatus,
): boolean {
  return VALID_TRANSITIONS[currentStatus]?.includes(newStatus) ?? false
}

/**
 * Update order status with validation.
 * The database trigger handles status_history and timestamps.
 */
export async function updateOrderStatus(
  orderId: string,
  newStatus: OrderStatus,
  _notes?: string,
): Promise<{ error: string | null }> {
  const client = supabase()
  if (!client) return { error: 'Supabase not configured' }

  // Fetch current status
  const { data: order, error: fetchError } = await client
    .from('orders')
    .select('status')
    .eq('id', orderId)
    .single()

  if (fetchError) return { error: fetchError.message }
  if (!order) return { error: 'Order not found' }

  if (!isValidTransition(order.status as OrderStatus, newStatus)) {
    return {
      error: `Invalid status transition: ${order.status} → ${newStatus}`,
    }
  }

  const { error } = await client
    .from('orders')
    .update({ status: newStatus })
    .eq('id', orderId)

  return { error: error?.message ?? null }
}
